function active$VoucherFilter$(f) {
  f.add_onResponseComplete(on$Filter$ResponseComplete);
  changeLookupReadonly(f, 'ma_dvcs');
  changeLookupReadonly(f, 'ma_bp');
  changeLookupReadonly(f, 'ma_vv');
  if (!f.getItemValue('tu_ky')) {
    var d = new Date();
    var y = d.getFullYear();
    var p = d.getMonth() + 1;
    f.setItemValues('tu_ky, tu_nam, den_ky, den_nam', [p, y, p, y]);
  }
  onChange$&controller;$Type(f);
  onChange$&controller;$PivotBy(f);
  &ReportSign.Filter.Active;
}
/* <flatten type="Javascript"> */
function close$VoucherFilter$(f) {try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
  var f = e.object, context = e.type.Context, result = e.type.Result;
  switch (context) {
    case 'Checking':
      var g = f.grid, periodF = f.getItem('tu_ky').value, yearF = f.getItem('tu_nam').value, periodT = f.getItem('den_ky').value, yearT = f.getItem('den_nam').value;
      var n = f.getItem('xoay_theo').selectedIndex, m = f.getItem('xoay_theo').options, reportBy = m[n].text, x = f.getItem('form').selectedIndex, y = f.getItem('form').options, formName = y[x].text;
      g._alterTitle = [null, [['%f', formName, true], ['%r', reportBy, true], ['%p1', periodF, true], ['%y1', yearF, true], ['%p2', periodT, true], ['%y2', yearT, true]]];

      var c = n + String.fromCharCode(255) + f.getItemValue('mau_bc');
      if (!g._v) g._v = c;
      if (g._v != c) {
        remove$GridReport$Filter(g);
        g._v = c;
      }
      break;
    default:
      break;
  }
}
/* </flatten> */
function onChange$&controller;$Item(o) {
  var f = o.parentForm, name = o.field.Name;
  switch (name) {
    case 'kieu_ns':
      onChange$&controller;$Type(f, true);
      break;
    case 'xoay_theo':
      onChange$&controller;$PivotBy(f, true);
      break;
    default:
      break;
  }
}
function onChange$&controller;$PivotBy(f, force) {window.setTimeout(String.format('onFocus$&controller;$PivotBy(\'{0}\', {1});', f._id, force ? 1 : 0), 2);}
function onFocus$&controller;$PivotBy(id, force) {
  var f = $find(id), x = f.getItemValue('xoay_theo'), bp = (x == 2), vv = (x == 3);
  setItem$&controller;$FieldsEmpty(f, 'ma_bp', bp)
  setItem$&controller;$Disable(f, 'ma_bp', !bp);
  setItem$&controller;$FieldsEmpty(f, 'ma_vv', vv)
  setItem$&controller;$Disable(f, 'ma_vv', !vv);
  setItem$&controller;$Disable(f, 'vvc_yn', !vv);
}
function onChange$&controller;$Type(f, force) {window.setTimeout(String.format('onFocus$&controller;$Type(\'{0}\', {1});', f._id, force ? 1 : 0), 2);}
function onFocus$&controller;$Type(id, force) {
  var f = $find(id), v = (f.getItem('kieu_ns').value == '3'), t1 = f.getItem('so_cs'), t2 = f.getItem('xoay_theo');
  setItem$&controller;$Disable(f, 'so_cs', !v);
  if (force) {
    if (v) {
      f.getItem('so_cs').disabled = false;
      f.getItem('so_cs').focus();
      f.live(f.getItem('so_cs'));
    } else {
      f.getItem('xoay_theo').focus();
      f.live(f.getItem('xoay_theo'));
    }
  }
}
function setItem$&controller;$Disable(f, c, v) {
  var a = c.split(',');
  for (var i = 0; i < a.length; i++) {
    var o = f.getItem($func.trim(a[i]));
    if (o.a) $common.setVisible(o.a, !v);
    o.disabled = v;
  }
}
function setItem$&controller;$FieldsEmpty(f, c, v) {
  var a = c.split(',');
  for (var i = 0; i < a.length; i++) {
    var o = f.getItem($func.trim(a[i]));
    if (!v) o.value = '';
  }
}
function init$&controller;$Form(f) {
  var o = f.getItem('form'), value = f._itemValue.split(String.fromCharCode(255)), text = f._itemText.split(String.fromCharCode(255)), index;
  for (var i = 0; i < value.length; i++) {
    o.options[i] = new Option(text[i], value[i]);
    if (!index && f._defaultForm == value[i]) index = i;
  }
  if (!index) index = 0;
  o.options[index].selected = true;
}




